    const c = old || { id: 'c' + fymd(now) + frnd(2), created: now, status: 'draft', st: {}, errs: [] }; Object.assign(c, r.v, { status: 'draft', updated: now }); await fput(env, 'nc:' + c.id, c); await ntQueue(env);
